// Derives the source of truth for the token-level `styles` prop from the
// authored component stylesheets (RRU-146).
//
// Why a generator: TypeScript cannot read a `.css` file in compile time, so the
// per-component token union has to be materialized as a value it can see. This
// script is that materialization. It uses the same regex as
// `packages/ui/src/test-support/css.ts:tokenVarsUsed`, and the vitest gate in
// `styles-type-contract.test.ts` compares the generated file back to the CSS so
// the two cannot drift.
//
// Run: `pnpm derive:styles`
import { readdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const srcDir = join(scriptDir, "..", "packages", "ui", "src");
const outFile = join(srcDir, "style-tokens.generated.ts");

/**
 * Mirrors `tokenVarsUsed` in `packages/ui/src/test-support/css.ts:82`.
 * Keep the two in sync; the equality gate will catch any divergence.
 */
function tokenVarsUsed(css) {
  const used = [...css.matchAll(/var\((--rr-[a-z0-9-]+)\)/g)].flatMap((match) =>
    match[1] === undefined ? [] : [match[1]],
  );
  // Same order as `test-support/css.ts`: deduplicated, first-occurrence order.
  return [...new Set(used)];
}

async function listComponentStylePaths() {
  const entries = await readdir(srcDir, { withFileTypes: true });
  const dirs = entries.filter((entry) => entry.isDirectory()).map((entry) => entry.name);

  const paths = [];
  for (const dir of dirs) {
    const files = await readdir(join(srcDir, dir), { withFileTypes: true });
    for (const file of files) {
      if (!file.isDirectory() && file.name.endsWith(".css")) {
        paths.push(`${dir}/${file.name}`);
      }
    }
  }

  return paths.sort();
}

function renderObjectLiteral(entries) {
  const lines = [];
  lines.push("export const styleTokens = {");
  for (const { dir, tokens } of entries) {
    lines.push(`  "${dir}": [`);
    for (const token of tokens) {
      lines.push(`    "${token}",`);
    }
    lines.push("  ] as const,");
  }
  lines.push("} as const;");
  return lines.join("\n");
}

async function main() {
  const paths = await listComponentStylePaths();
  if (paths.length === 0) {
    throw new Error(`no component stylesheets found under ${srcDir}`);
  }

  const entries = await Promise.all(
    paths.map(async (path) => {
      const css = await readFile(join(srcDir, path), "utf8");
      const dir = path.split("/")[0];
      if (dir === undefined) {
        throw new Error(`unexpected stylesheet path ${path}`);
      }
      return { dir, tokens: tokenVarsUsed(css) };
    }),
  );

  const totalTokens = entries.reduce((sum, { tokens }) => sum + tokens.length, 0);
  if (totalTokens === 0) {
    throw new Error("no --rr-* tokens consumed by any component stylesheet");
  }

  const header = [
    "// Generated by tools/derive-style-types.mjs — DO NOT EDIT. (RRU-146)",
    "// This file is the single source of truth for the token-level `styles` prop.",
    "// Run `pnpm derive:styles` after editing any component CSS.",
    "",
  ].join("\n");

  const body = [
    renderObjectLiteral(entries),
    "",
    "export type StyleTokenKey = keyof typeof styleTokens;",
    "",
    "export type Styles<K extends StyleTokenKey> = Partial<",
    "  Record<(typeof styleTokens)[K][number], string>,",
    ">;",
    "",
  ].join("\n");

  await writeFile(outFile, `${header}${body}`, "utf8");

  console.log(
    `generated ${outFile} from ${paths.length} stylesheets (${totalTokens} token references)`,
  );
}

main().catch((error) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error(message);
  process.exit(1);
});
